  customerIdentityMatched:true,sourceChannel:'MESSENGER',
  sourceIdentityApproved:true,targetIdentityApproved:true,
  quantity:1,expectedTotalVnd:159000,stock:10,
  customerConfirmed:true,rawText:'Tôi muốn biết sản phẩm',expected,qaOnly:true,
  ...patch};
 cases.push(c);
}
