const profilesB=[
 {channel:'MESSENGER',installationId:'QA_META_B',destinationId:'QA_PAGE_B'},
 {channel:'ZALO',installationId:'QA_ZALO_B',destinationId:'QA_OA_B'},
 {channel:'WEBSITE',installationId:'QA_WEB_B',destinationId:'QA_SITE_B'}
];
for(const p of profilesB){
 const own={sku:'SKU_B_001',requestedOrderId:'ORDER_B_001',
   orderGrantStore:'STORE_B',orderGrantCustomer:'CUSTOMER_B',
   expectedTotalVnd:189000};
 add(p,'same tenant B own catalog',own,'SIMULATED_READ_ONLY');
 add(p,'same tenant B own order status',{...own,action:'READ_OWN_ORDER_STATUS'},'SIMULATED_READ_ONLY');
 add(p,'same tenant B quoted order preview',{...own,action:'PROPOSE_ORDER'},'SIMULATED_PROPOSAL');
 add(p,'same tenant B cannot read A SKU',{...own,sku:'SKU_A_001'},'DENY');
 add(p,'same tenant B cannot read A order',{...own,action:'READ_OWN_ORDER_STATUS',requestedOrderId:'ORDER_A_001'},'DENY');
