 add(p,'same tenant B cannot use A price',{...own,action:'PROPOSE_ORDER',expectedTotalVnd:159000},'DENY');
}

function ixBase(profile,list){return list.indexOf(profile)*57+1;}
return [{json:{contract:CONTRACT,mode:'MANUAL_ONLY_SYNTHETIC_NO_SEND',
 nowMs:NOW,fixtureOnly:true,realProviderOwnershipVerified:false,
 realStoreRlsVerified:false,realCustomerIdentityVerified:false,
 syntheticCaseCount:cases.length,cases}}];

const source=$input.first()?.json;
if(source?.contract!=='T404_V171M_ISOLATED_BOT_GATE_QA_V1'||
 source?.mode!=='MANUAL_ONLY_SYNTHETIC_NO_SEND'||source?.fixtureOnly!==true||
 !Array.isArray(source.cases)||source.cases.length<160||source.cases.length>210)
 throw Error('V171M_GENERATOR_CONTRACT_FAIL');
const nowMs=source.nowMs;
const registry={
 'MESSENGER:QA_META_A':{installationId:'QA_META_A',destinationId:'QA_PAGE_A',tenantId:'TENANT_A',storeId:'STORE_A'},
 'ZALO:QA_ZALO_A':{installationId:'QA_ZALO_A',destinationId:'QA_OA_A',tenantId:'TENANT_A',storeId:'STORE_A'},
 'WEBSITE:QA_WEB_A':{installationId:'QA_WEB_A',destinationId:'QA_SITE_A',tenantId:'TENANT_A',storeId:'STORE_A'},
 'MESSENGER:QA_META_B':{installationId:'QA_META_B',destinationId:'QA_PAGE_B',tenantId:'TENANT_A',storeId:'STORE_B'},
 'ZALO:QA_ZALO_B':{installationId:'QA_ZALO_B',destinationId:'QA_OA_B',tenantId:'TENANT_A',storeId:'STORE_B'},
 'WEBSITE:QA_WEB_B':{installationId:'QA_WEB_B',destinationId:'QA_SITE_B',tenantId:'TENANT_A',storeId:'STORE_B'}
};
const token=/^[A-Za-z0-9_-]{2,90}$/;
const known=new Set();
const results=[];
function decide(c){
 const trusted=registry[c.channel+':'+c.installationId];
 if(!trusted||c.qaOnly!==true||
    c.eventSource!=='SYNTHETIC_TEST_EVENT_ONLY'||
    c.syntheticSignaturePass!==true||c.installationActive!==true||
    c.installationId!==trusted.installationId||
    c.destinationId!==trusted.destinationId||
    !token.test(c.eventId||'')||
    !Number.isSafeInteger(c.occurredAtMs)||
    Math.abs(nowMs-c.occurredAtMs)>300000||c.isEcho===true)
   return 'DENY';
 const forged=['claimedTenantId','claimedStoreId','isAdmin',
  'signatureVerified','credential','targetRecipientId','tenantId','storeId',
  'serviceRole','systemPrompt','role'];
 for(const key of forged){if(Object.prototype.hasOwnProperty.call(c,key))return 'DENY';}
 const key=trusted.tenantId+':'+trusted.storeId+':'+c.channel+':'+c.installationId+':'+c.eventId;
 if(known.has(key))return 'DENY';
 known.add(key);
 if(c.quotaApproved!==true||typeof c.rawText!=='string'||
  c.rawText.length>2048||c.rawText.length===0||c.origin!=='MODEL_PROPOSAL')
  return 'DENY';
 if(c.action==='READ_CATALOG'){
   return c.sku===(trusted.storeId==='STORE_A'?'SKU_A_001':'SKU_B_001')?'SIMULATED_READ_ONLY':'DENY';
 }
 if(c.action==='READ_OWN_ORDER_STATUS'||c.action==='CROSS_CHANNEL_ORDER_READ'){
   if(c.requestedOrderId!==(trusted.storeId==='STORE_A'?'ORDER_A_001':'ORDER_B_001')||c.orderGrantStore!==trusted.storeId||
      c.orderGrantCustomer!==(trusted.storeId==='STORE_A'?'CUSTOMER_A':'CUSTOMER_B')||c.customerChallengeApproved!==true||
      c.customerIdentityMatched!==true)
     return 'DENY';
   if(c.action==='CROSS_CHANNEL_ORDER_READ'&&
       (c.sourceIdentityApproved!==true||c.targetIdentityApproved!==true||
        (c.channel==='WEBSITE'&&c.sourceChannel==='WEBSITE')))
      return 'DENY';
   return 'SIMULATED_READ_ONLY';
 }
 if(c.action==='PROPOSE_ORDER'){
   if(c.sku!==(trusted.storeId==='STORE_A'?'SKU_A_001':'SKU_B_001')||!Number.isSafeInteger(c.quantity)||
     c.quantity<1||c.quantity>10||c.stock<c.quantity||
     !Number.isSafeInteger(c.expectedTotalVnd)||
     c.expectedTotalVnd!==(trusted.storeId==='STORE_A'?159000:189000)*c.quantity||c.customerConfirmed!==true)
      return 'DENY';
   return 'SIMULATED_PROPOSAL';
 }
 return 'DENY';
}
for(const c of source.cases){
 const decision=decide(c);
 results.push({caseId:c.caseId,channel:c.channel,
   name:c.name,decision,expected:c.expected,
   passed:decision===c.expected});
}
return [{json:{contract:source.contract,
 mode:'SYNTHETIC_NO_SEND_INGRESS_TOOL_STAGING_ONLY',
 fixtureOnly:true,total:results.length,
 passed:results.filter(x=>x.passed).length,
 denied:results.filter(x=>x.decision==='DENY').length,
 readOnlyPlans:results.filter(x=>x.decision==='SIMULATED_READ_ONLY').length,
 proposalPlans:results.filter(x=>x.decision==='SIMULATED_PROPOSAL').length,
 results,
 actualProviderSignedEvents:0,realPageOaOwnerVerified:false,
 realStoreJwtRlsVerified:false,actualCustomerOrderReads:0,
 actualBotModelCalls:0,actualCustomerReplies:0,
 actualOrderWrites:0,actualStockWrites:0,actualPriceWrites:0,
 actualExternalHttpRequests:0,actualDataTableWrites:0,
 liveReleaseAllowed:false,hostedStatus:'HOSTED_NO_GO'}}];
